#!/usr/bin/env Rscript
# Synthetic data/provenance; actual validator and test-wrapper execution.
repo_root<-normalizePath(if(length(commandArgs(TRUE)))commandArgs(TRUE)[[1]] else ".")
source(file.path(repo_root,"methodology/tests/fixtures.R"))
env<-new.env(parent=globalenv());lines<-readLines(file.path(repo_root,"workflow-gate/tests/test_workflow_gate.R"));eval(parse(text=lines[seq_len(grep('^pass_root <-',lines)[[1]]-1L)]),env)
root<-tempfile("remediation-");dir.create(root);env$write_project(root)
s3<-m_read(file.path(root,"artifacts/stage3_locked_design.json"));s4<-m_read(file.path(root,"artifacts/stage4_validation_status.json"));r<-m_read(file.path(root,s4$evidence_receipts$methodology$path))
results<-list();check<-function(name,value){ok<-isTRUE(value);results[[name]]<<-ok;cat(if(ok)"PASS" else "FAIL",name,"\n")}
check("current validation accepted",m_pass(m_validation(s3,r,root)))
code<-file.path(root,"code/analysis.R");original<-readLines(code);writeLines(c(original,"# harmless one-line change"),code)
check("changed code invalidates validation",!m_pass(m_validation(s3,r,root)))
x<-r;x$test_versions$components<-lapply(s3$methodology$operational$validation_components,function(paths)lapply(paths,m_file_ref,root=root));x$test_versions$tests<-lapply(x$test_versions$tests,function(t){t$components<-x$test_versions$components;t})
check("wrapper-only hashes insufficient",!m_pass(m_validation(s3,x,root)))
x$test_versions$tests<-lapply(x$test_versions$tests,function(t)m_bound_test(t$id,x$test_versions$components,root,function()TRUE))
check("new bound reports accepted",m_pass(m_validation(s3,x,root)))
writeLines(original,code)
y<-s3;y$methodology$operational$fixture_inputs<-NULL;check("missing frozen fixture rejected",!m_pass(m_design(y,root=root)))
y<-s3;y$methodology$operational$output_rules<-list();check("missing output rules rejected",!m_pass(m_design(y,root=root)))
check("action whole word and underscore",m_words("no_price_increase",list("increase")) && !m_words("inactive",list("act")))
now<-format(Sys.time(),"%Y-%m-%dT%H:%M:%SZ",tz="UTC")
t_write(root,"artifacts/procedure/checks/start-begin.json",list(step="start",phase="begin",result="PASS",checked_at_utc=now))
state<-list(run_id="SYNTHETIC",current_step="start",current_authorization=m_file_ref("artifacts/procedure/checks/start-begin.json",root))
t_write(root,"artifacts/procedure/run_state.json",state);t_operations(root,"start")
op_path<-"artifacts/operations/start.json";o<-m_read(file.path(root,op_path))
check("valid recorded operations",m_pass(m_operations(root,state,"start")))
bad<-function(name,alter){t_write(root,op_path,alter(o));check(name,!m_pass(m_operations(root,state,"start")));t_write(root,op_path,o)}
bad("send before begin rejected",function(x){x$sends[[1]]$ready_at_utc<-"2020-01-01T00:00:00Z";x})
bad("future capture rejected",function(x){x$sends[[1]]$verified_at_utc<-"2099-01-01T00:00:00Z";x})
bad("failed approval condition rejected",function(x){x$approvals[[1]]$conditions<-list(list(condition="test",status="FAIL",evidence=x$transcript_index));x})
bad("expired approval rejected",function(x){x$approvals[[1]]$expires_at_utc<-"2020-01-01T00:00:00Z";x})
bad("wrong authorization rejected",function(x){x$authorization$sha256<-paste(rep("0",64),collapse="");x})
bad("missing sends rejected",function(x){x$sends<-list();x})
bad("missing packet rejected",function(x){x$sends[[1]]$packet$path<-"missing.json";x})
bad("undeclared dependency rejected",function(x){x$sends[[1]]$depends_on<-list("missing-send");x})
replypath<-o$sends[[1]]$reply$path;reply<-readLines(file.path(root,replypath));writeLines("Old stale reply END_REPLY wrong nonce",file.path(root,replypath))
bad("rehashed stale reply rejected",function(x){x$sends[[1]]$reply<-m_file_ref(replypath,root);x});writeLines(reply,file.path(root,replypath))
t_write(root,"artifacts/operations/revocations.json",list(run_id=state$run_id,events=list(list(approval_id=o$approvals[[1]]$id,recorded_at_utc=now,owner_record=o$approvals[[1]]$owner_record))))
check("recorded revocation rejected",!m_pass(m_operations(root,state,"start")))
bound<-m_bound_test("actual-test",r$test_versions$components,root,function()sum(c(9,10,11))==30)
check("actual test wrapper passes",identical(bound$result,"PASS"))
bound<-m_bound_test("mutation-test",r$test_versions$components,root,function(){writeLines("changed",code);TRUE})
check("mutation during test fails",identical(bound$result,"FAIL"));writeLines(original,code)
t_write(root,"closure.json",list(child=list(path="missing.txt",sha256=paste(rep("0",64),collapse=""))))
check("missing transitive inventory fails",inherits(try(m_inventory(list(m_file_ref("closure.json",root)),root),silent=TRUE),"try-error"))
cat(sum(unlist(results)),"/",length(results),"remediation tests passed\n")
if(!all(unlist(results)))quit(status=1)
